-- Isolated fixtures only; no production users or emails.
begin;
create extension if not exists pgtap;
select no_plan();
select ok(not has_function_privilege('anon','public.can_write_team_media(text)','execute'),'anonymous media helper execution revoked');
insert into public.profiles(id,email,role) values('user_teamowner','owner@example.test','admin'),('user_teammember','member@example.test','customer'),('user_teamother','other@example.test','customer');
insert into public.team_access(user_id,role,permissions,granted_by) values('user_teammember','admin',array['products','categories','orders','customers','content','reviews','analytics'],'user_teamowner');
select set_config('request.jwt.claims','{"sub":"user_teammember","role":"authenticated"}',true);
set local role authenticated;
select ok(not public.is_admin(),'Admin is not an Owner');
select ok(public.has_team_permission('products'),'Admin can manage products');
select ok(public.has_team_permission('orders'),'Admin can manage orders');
select ok(not public.has_team_permission('settings'),'Admin cannot manage settings');
select is((select count(*) from public.team_invitations),0::bigint,'Admin cannot read invitation directory');
select throws_ok($$update public.team_access set role='super_admin' where user_id='user_teammember'$$,'42501',null,'Admin cannot promote own role');
select throws_ok($$select public.team_prepare_invitation('user_teamowner','victim@example.test','{}',true,'owner')$$,'42501',null,'client cannot impersonate an inviter through RPC');
select throws_ok($$select public.team_accept_invitation('73000000-0000-4000-8000-000000000001','user_teammember','member@example.test')$$,'42501',null,'acceptance RPC is service-only');
select lives_ok($$select public.admin_dashboard_stats(now()-interval '1 day',now())$$,'Admin can view analytics');
select throws_ok($$select public.admin_save_shipping('[]')$$,'42501',null,'Admin cannot save shipping');
select ok(public.can_write_team_media('products/test.webp'),'product media allowed');
select ok(not public.can_write_team_media('brand/test.webp'),'brand media restricted');
select ok(public.can_write_team_media('avatars/user_teammember/test.webp'),'own avatar allowed');
select ok(not public.can_write_team_media('avatars/user_teamowner/test.webp'),'another avatar restricted');
reset role;
select throws_ok($$update public.team_access set permissions=array['settings'] where user_id='user_teammember'$$,'23514',null,'roles cannot acquire custom permissions');
create temporary table team_test_invite(id uuid);
insert into team_test_invite select (public.team_prepare_invitation('user_teamowner','member@example.test',array['products','categories','orders','customers','content','reviews','analytics','settings'],false,'super_admin')->>'id')::uuid;
update public.team_invitations set status='pending' where id=(select id from team_test_invite);
select throws_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teamother','other@example.test')$$,'P0001',null,'wrong verified email rejected');
select lives_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teammember','member@example.test')$$,'existing member accepts Super Admin invitation');
select is(public.effective_team_role('user_teammember'),'super_admin','role persisted');
select lives_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teammember','member@example.test')$$,'accept retry idempotent');
select is((select count(*) from public.profiles),3::bigint,'acceptance does not duplicate profiles');
select throws_ok($$select public.team_prepare_invitation('user_teammember','another@example.test','{}',true,'owner')$$,'42501',null,'Super Admin cannot invite Owner');
select throws_ok($$select public.team_prepare_invitation('user_teammember','another@example.test',array['products','categories','orders','customers','content','reviews','analytics','settings'],false,'super_admin')$$,'42501',null,'Super Admin cannot invite peers');
truncate team_test_invite;
insert into team_test_invite select (public.team_prepare_invitation('user_teammember','other@example.test',array['products','categories','orders','customers','content','reviews','analytics'],false,'admin')->>'id')::uuid;
update public.team_invitations set status='pending',expires_at=now()-interval '1 second' where id=(select id from team_test_invite);
select throws_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teamother','other@example.test')$$,'P0001',null,'expired invitation rejected');
update public.team_invitations set status='revoked',expires_at=now()+interval '1 day' where id=(select id from team_test_invite);
select throws_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teamother','other@example.test')$$,'P0001',null,'revoked invitation rejected');
update public.team_invitations set status='pending' where id=(select id from team_test_invite);
select lives_ok($$select public.team_accept_invitation((select id from team_test_invite),'user_teamother','other@example.test')$$,'Super Admin can invite Admin');
select throws_ok($$select public.team_set_access('user_teammember','user_teamother','{}',true,'owner')$$,'42501',null,'Super Admin cannot promote Admin to Owner');
select throws_ok($$select public.team_set_access('user_teammember','user_teamowner','{}',false,null)$$,'P0001',null,'Owner is protected');
select throws_ok($$select public.team_set_access('user_teamowner','user_teamowner','{}',false,null)$$,'P0001',null,'self changes blocked');
select lives_ok($$select public.team_set_access('user_teammember','user_teamother','{}',false,null)$$,'Super Admin can remove Admin');
select is(public.effective_team_role('user_teamother'),null,'removed Admin loses studio role');
select is((select count(*) from public.profiles where id='user_teamother'),1::bigint,'customer account preserved');
select set_config('request.jwt.claims','{"sub":"user_teammember","role":"authenticated"}',true);
set local role authenticated;
select ok(public.has_team_permission('settings'),'Super Admin has store settings');
select lives_ok($$select public.admin_save_shipping('[]')$$,'Super Admin can save shipping');
reset role;
select * from finish();
rollback;
